INSERT INTO `v1_bc9c943d6415223830b63552eeccee9020d029dd2284487e9efdd8abb9936985` VALUES (101831, 0, 312001, 0, 11, 312, 8, 0, "素敵な新年会ね～\n他の学校の人たちも来ているようだし\nお話を伺いに行こうかしら？", 0, 0.5);
INSERT INTO `v1_bc9c943d6415223830b63552eeccee9020d029dd2284487e9efdd8abb9936985` VALUES (101831, "", 312002, 0.2, 3, 312, 1, "", "nop_talk_joy1", "", "");
