INSERT INTO `v1_bc9c943d6415223830b63552eeccee9020d029dd2284487e9efdd8abb9936985` VALUES (105331, 0, 313001, 0, 11, 313, 8, 0, "立派な新年会ではないか。\n我々もこの場に相応しく\n振る舞わなければな！", 0, 0.5);
INSERT INTO `v1_bc9c943d6415223830b63552eeccee9020d029dd2284487e9efdd8abb9936985` VALUES (105331, 0.2, 313002, 0.2, 3, 313, 0, "nop_13_monica_talk_doya_loop", "nop_13_monica_talk_doya", 1, "");
