INSERT INTO `v1_bc9c943d6415223830b63552eeccee9020d029dd2284487e9efdd8abb9936985` VALUES (103031, 0, 313005, 0, 11, 313, 8, 0, "おせちといえばトーゴクデース！\nオーエド町のみなさんにも\n新年のゴアイサツしないとデスね！", 0, 0.5);
INSERT INTO `v1_bc9c943d6415223830b63552eeccee9020d029dd2284487e9efdd8abb9936985` VALUES (103031, "", 313006, 0.2, 3, 313, 1, "", "nop_talk_joy1", "", "");
