INSERT INTO `v1_bc9c943d6415223830b63552eeccee9020d029dd2284487e9efdd8abb9936985` VALUES (100811, 0, 313009, 0, 11, 313, 8, 0, "新年会でもボクは美しいね。\nああ、会場中の視線が\n集まってるようだよ。", 0, 0.5);
INSERT INTO `v1_bc9c943d6415223830b63552eeccee9020d029dd2284487e9efdd8abb9936985` VALUES (100811, "", 313010, 0.2, 3, 313, 1, "", "nop_talk_thinking", "", "");
