INSERT INTO `v1_bc9c943d6415223830b63552eeccee9020d029dd2284487e9efdd8abb9936985` VALUES (104511, 0, 313013, 0, 11, 313, 8, 0, "会場中の視線……\nああ、蔑みの視線がクウカに……\nぐふふふ……", 0, 0.5);
